// KVM density index — record JAH-GPC-KVMSWITCH-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"ports": 2, "max_res_mp": 8.3, "price_usd": 80};
var value = (m.ports*m.max_res_mp/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-KVMSWITCH-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-KVMSWITCH-000001|' + value.toFixed(2) + ' density index');

